import app from '../../admin/app';
import Component from '../../common/Component';

/**
 * The favicon at the sizes browsers show it in tabs: 16px, and 32px on
 * high-resolution screens.
 */
export default class FaviconPreview extends Component {
  view() {
    const favicon = app.forum.attribute('faviconUrl');
    if (!favicon) return null;
    return m("div", {
      className: "FaviconPreview"
    }, [16, 32].map(size => m("span", {
      className: "FaviconPreview-tab"
    }, m("img", {
      src: favicon,
      alt: "",
      width: size,
      height: size
    }), m("span", {
      className: "FaviconPreview-title"
    }, app.forum.attribute('title')))));
  }
}
flarum.reg.add('core', 'admin/components/FaviconPreview', FaviconPreview);